import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const BUNDLE = here("../../custom_components/storage_manager/frontend/storage-manager-panel.js");
const FIXTURES = here("./fixtures/ws.json");

const PAGE = `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>body{margin:0;font-family:sans-serif}</style></head><body>
<script type="module">
const params = new URLSearchParams(location.search);
// Home Assistant's default themes, for the colour contrast check
const THEMES = {
  light: "--primary-color:#009ac7;--primary-text-color:#141414;--secondary-text-color:#5e5e5e;--card-background-color:#fff;--primary-background-color:#fafafa;--divider-color:rgba(0,0,0,.12);--error-color:#db4437;--warning-color:#ffa600;--success-color:#43a047;--info-color:#039be5;--text-primary-color:#fff;--app-header-background-color:#fff;--app-header-text-color:#141414",
  dark: "--primary-color:#009ac7;--primary-text-color:#e1e1e1;--secondary-text-color:#9b9b9b;--card-background-color:#1c1c1c;--primary-background-color:#111111;--divider-color:rgba(225,225,225,.12);--error-color:#db4437;--warning-color:#ffa600;--success-color:#43a047;--info-color:#039be5;--text-primary-color:#fff;--app-header-background-color:#101e24;--app-header-text-color:#e1e1e1",
};
if (THEMES[params.get("theme")]) {
  const style = document.createElement("style");
  style.textContent = "storage-manager-panel{" + THEMES[params.get("theme")] + "}";
  document.head.appendChild(style);
}
const lang = params.get("lang") || "en";
const fixtures = await (await fetch("/fixtures.json")).json();
// the recorded instance sets some recorder keys in YAML; a test can lift that
if (params.get("unlocked")) fixtures.overview.data.recorder.locked_settings = {};
const calls = [];
window.__calls = calls;
// what the panel's changes answer: enough for the flows, nothing is changed
const answers = {
  apply: { restart_required: false, packages_missing: false, blocked: null, backup: null, undo: null, status: fixtures.overview.data.recorder },
  clean: { freed: 0, results: {}, errors: [], blocked: null, backup: null, undo: null },
  folder_browse: fixtures.folder_scan,
  subscribe: null,
};
const states = {};
for (const row of fixtures.entities.rows) states[row.entity_id] = { entity_id: row.entity_id, state: "1", attributes: { friendly_name: row.name } };
window.hass = {
  language: lang,
  locale: { language: lang },
  states,
  localize: () => "",
  callService: async () => undefined,
  callWS: async (msg) => {
    const type = msg.type.replace("storage_manager/", "");
    calls.push(msg);
    if (type in fixtures) return structuredClone(fixtures[type]);
    if (type in answers) return structuredClone(answers[type]);
    throw new Error("no fixture for " + type);
  },
  connection: { subscribeMessage: async () => () => undefined },
};
await import("/panel.js");
const panel = document.createElement("storage-manager-panel");
panel.hass = window.hass;
panel.narrow = innerWidth < 870;
panel.route = { path: "" };
panel.panel = { config: {} };
document.body.appendChild(panel);
window.__ready = true;
</script></body></html>`;

export async function startServer() {
  const bundle = await readFile(BUNDLE);
  const fixtures = await readFile(FIXTURES);
  const server = createServer((req, res) => {
    const path = new URL(req.url, "http://x").pathname;
    if (path === "/panel.js") {
      res.writeHead(200, { "content-type": "text/javascript" });
      res.end(bundle);
    } else if (path === "/fixtures.json") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(fixtures);
    } else {
      res.writeHead(200, { "content-type": "text/html" });
      res.end(PAGE);
    }
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address();
  return { url: `http://127.0.0.1:${port}/`, close: () => new Promise((r) => server.close(r)) };
}
